const imiona = new Set(["Ala", "Bea", "Ala", "Cela"]);
imiona.delete("Bea");
console.log(imiona); // Set(2) {"Ala", "Cela"}

const liczby = new Set([2, 4, 6]);
console.log(liczby.has(4)); // true
liczby.delete(4);
console.log(liczby.has(4)); // false

const zbior = new Set([1, "1", true, 1]);
console.log(zbior.size); // 3
// Set rozroznia typy wartosci, wiec liczba 1 (number) i string "1" to
// DWIE ROZNE wartosci, mimo ze "wygladaja podobnie". Wartosc true rowniez
// jest osobnym typem (boolean). Druga liczba 1 w tablicy jest DUPLIKATEM
// pierwszej (ten sam typ i wartosc), wiec zostaje odrzucona - stad size = 3
// (1, "1", true), a nie 4.

const zbior = new Set([5, 5, 7, 7, 7, 9]);
const tablica = [...zbior];
console.log(tablica); // [5, 7, 9]

const litery = new Set(["a", "b", "c"]);
for (const litera of litery) {
  console.log(litera);
}
// a, b, c

const oceny = [3, 4, 4, 5, 5, 5, 2];
const unikalneOceny = [...new Set(oceny)];
console.log(unikalneOceny); // [3, 4, 5, 2]

const litery = new Set("mississippi");
console.log(litery.size); // -> 4
console.log([...litery]); // -> ["m", "i", "s", "p"]

const zdanie = "to jest to samo zdanie to jest";
const unikalne = new Set(zdanie.split(" "));
console.log(unikalne.size); // -> 4
console.log([...unikalne]); // -> ["to", "jest", "samo", "zdanie"]

function suma(a, b) {
  return [...new Set([...a, ...b])];
}

console.log(suma([1, 2, 3], [3, 4, 5])); // -> [1, 2, 3, 4, 5]

function czescWspolna(a, b) {
  const zbior = new Set(b);
  return [...new Set(a)].filter(x => zbior.has(x));
}

console.log(czescWspolna([1, 2, 3, 4], [3, 4, 5])); // -> [3, 4]

function roznica(a, b) {
  const zbior = new Set(b);
  return a.filter(x => !zbior.has(x));
}

console.log(roznica([1, 2, 3, 4], [3, 4, 5])); // -> [1, 2]

function maDuplikaty(tablica) {
  return new Set(tablica).size !== tablica.length;
}

console.log(maDuplikaty([1, 2, 3])); // -> false
console.log(maDuplikaty([1, 2, 2])); // -> true

const osoba = { imie: "Ala" };
const zbior = new Set();
zbior.add(osoba).add(osoba).add({ imie: "Ala" });

console.log(zbior.size);                 // -> 2
console.log(zbior.has(osoba));           // -> true
console.log(zbior.has({ imie: "Ala" })); // -> false (nowy obiekt to inna referencja)

const s = new Set(["a", "b"]);

s.forEach((wartosc, klucz, zbior) => {
  console.log(wartosc, klucz, zbior === s);
});
// -> "a" "a" true
// -> "b" "b" true
// W Set klucz i wartosc to to samo - podpis zachowano dla zgodnosci z Map.

const s = new Set([3, 1, 2]);
console.log([...s]); // -> [3, 1, 2]

s.add(1);
console.log([...s]); // -> [3, 1, 2] (bez zmian)

s.delete(3);
s.add(3);
console.log([...s]); // -> [1, 2, 3] (3 trafilo na koniec)

const s = new Set([1, 2, 3]);
const odwiedzone = [];

for (const x of s) {
  odwiedzone.push(x);
  if (x < 3) s.add(x + 3);
}

console.log(odwiedzone); // -> [1, 2, 3, 4, 5]
// Elementy dodane w trakcie iteracji (4 i 5) tez zostaly odwiedzone.

const dane = [3, 1, 3, 2, 1];
const posortowane = [...new Set(dane)].sort((a, b) => a - b);
console.log(posortowane); // -> [1, 2, 3]

const zbior = new Set(posortowane);
console.log(zbior.size);  // -> 3

function przelacz(tagi, tag) {
  if (tagi.has(tag)) {
    tagi.delete(tag);
    return false;
  }
  tagi.add(tag);
  return true;
}

const tagi = new Set(["js"]);
console.log(przelacz(tagi, "css")); // -> true
console.log(przelacz(tagi, "js"));  // -> false
console.log([...tagi]);             // -> ["css"]

function czyPodzbior(a, b) {
  const zbior = new Set(b);
  return a.every(x => zbior.has(x));
}

console.log(czyPodzbior([1, 2], [1, 2, 3])); // -> true
console.log(czyPodzbior([1, 4], [1, 2, 3])); // -> false

function roznicaSymetryczna(a, b) {
  const sa = new Set(a);
  const sb = new Set(b);
  return [...a.filter(x => !sb.has(x)), ...b.filter(x => !sa.has(x))];
}

console.log(roznicaSymetryczna([1, 2, 3], [2, 3, 4])); // -> [1, 4]

const dane = [{ id: 1 }, { id: 2 }, { id: 1 }];
const widziane = new Set();

const unikalne = dane.filter(o => {
  if (widziane.has(o.id)) return false;
  widziane.add(o.id);
  return true;
});

console.log(unikalne); // -> [{ id: 1 }, { id: 2 }]

function pierwszyDuplikat(tablica) {
  const widziane = new Set();
  for (const x of tablica) {
    if (widziane.has(x)) return x;
    widziane.add(x);
  }
  return undefined;
}

console.log(pierwszyDuplikat([2, 1, 3, 1, 2])); // -> 1
console.log(pierwszyDuplikat([1, 2, 3]));       // -> undefined

class Tagi {
  #zbior = new Set();

  dodaj(t) {
    this.#zbior.add(t);
    return this;
  }

  usun(t) {
    return this.#zbior.delete(t);
  }

  zawiera(t) {
    return this.#zbior.has(t);
  }

  get ile() {
    return this.#zbior.size;
  }
}

const tagi = new Tagi().dodaj("js").dodaj("css").dodaj("js");
console.log(tagi.ile);            // -> 2
console.log(tagi.zawiera("js"));  // -> true

const s = new Set([10, 20]);

console.log(s[0]);     // -> undefined (Set nie ma indeksow)
console.log(s.length); // -> undefined (jest size, nie length)
console.log(s.size);   // -> 2
// Set: gdy liczy sie unikalnosc i szybkie sprawdzanie obecnosci (has). Tablica: gdy liczy sie kolejnosc, indeksy, duplikaty.

function unikalneSlowa(tekst) {
  return [...new Set(tekst.toLowerCase().split(" "))].sort();
}

console.log(unikalneSlowa("Kot ala kot Ala pies")); // -> ["ala", "kot", "pies"]

